package gen

import (
	"bytes"
	"fmt"
	"path"
	"sort"
	"strings"

	"github.com/junikimm717/static-python/src/staticpy/internal/assets"
	"github.com/junikimm717/static-python/src/staticpy/internal/config"
)

// sectionMarker splits the Setup asset into module sets. Everything before the
// first marker is the makesetup preamble and is always emitted.
const sectionMarker = "#staticpy:section "

// The staticapi module is the whole reason ctypes works in a static build; the
// symbols.c half is generated by StaticAPI, not shipped.
const staticapiLine = "staticapi staticapi/symbols.c staticapi/staticapi.c"

// Modules == "minimal" is the pyhost set: no OpenSSL, no libffi, no sqlite, not
// even zlib. deepfreeze.py imports only pure-Python modules, and
// freeze_modules.py's hashlib falls back to the builtin _sha2/_md5.
func SetupLocal(cfg config.Resolved, extra []config.PyModule) ([]byte, error) {
	preamble, sections, err := parseSetupAsset(assets.MustGet("Setup"))
	if err != nil {
		return nil, err
	}

	want := []string{"core"}
	switch cfg.Modules {
	case "", "full":
		want = append(want, "full")
	case "minimal":
	default:
		return nil, fmt.Errorf("gen: unknown module set %q", cfg.Modules)
	}
	if cfg.TestModules {
		want = append(want, "test")
	}

	var b bytes.Buffer
	b.WriteString("# Generated by staticpy. Edits here are lost on the next build.\n")
	fmt.Fprintf(&b, "# profile=%s scope=%s modules=%s test_modules=%t\n\n",
		cfg.Profile, cfg.Scope, orFull(cfg.Modules), cfg.TestModules)
	b.Write(preamble)

	for _, name := range want {
		body, ok := sections[name]
		if !ok {
			return nil, fmt.Errorf("gen: Setup asset has no %q section", name)
		}
		b.Write(body)
	}

	// pyhost never imports ctypes, so the 900-entry symbol table is pure weight
	// there.
	if cfg.Modules != "minimal" {
		// *static* is re-asserted rather than inherited: makesetup carries the
		// last mode tag forward, and the test section ends in a *disabled* block.
		b.WriteString("\n*static*\n" + staticapiLine + "\n")
	}

	if len(extra) > 0 {
		b.WriteString("\n# Bundled packages\n\n*static*\n\n")
		for _, m := range extra {
			line, err := moduleLine(m)
			if err != nil {
				return nil, err
			}
			b.WriteString(line + "\n")
		}
	}
	return b.Bytes(), nil
}

func orFull(m string) string {
	if m == "" {
		return "full"
	}
	return m
}

// BundleFile is written under Modules/ after the sdist is staged.
type BundleFile struct {
	Path    string
	Content []byte
}

// RewriteModule prefixes sources with Modules/_bundle/<pkg>/ and adds -I for
// each source directory. -Dname=value cannot go on the Setup.local line:
// makesetup treats any `=` as a Makefile assignment and then `make` dies
// with "missing separator". Those macros become a generated wrapper that
// #defines them and #includes the real .c.
func RewriteModule(pkg string, m config.PyModule) (config.PyModule, []BundleFile, error) {
	if err := config.RelPath(pkg); err != nil {
		return m, nil, fmt.Errorf("gen: package %q: %w", pkg, err)
	}
	var defines []string
	if d := initRenameMacro(m); d != "" {
		defines = append(defines, d)
	}
	var keep []string
	for _, f := range m.CFlags {
		if name, val, ok := cutDashD(f); ok {
			if val == "" {
				defines = append(defines, name)
			} else {
				defines = append(defines, name+" "+val)
			}
			continue
		}
		if strings.Contains(f, "=") {
			return m, nil, fmt.Errorf("gen: module %q: flag %q contains =; makesetup would copy the line into the Makefile as an assignment", m.Name, f)
		}
		keep = append(keep, f)
	}

	out := m
	out.Sources = make([]string, len(m.Sources))
	dirs := map[string]struct{}{}
	var files []BundleFile
	for i, src := range m.Sources {
		if err := config.RelPath(src); err != nil {
			return m, nil, fmt.Errorf("gen: module %q source: %w", m.Name, err)
		}
		orig := path.Join("_bundle", pkg, src)
		dirs[path.Dir(orig)] = struct{}{}
		if len(defines) == 0 {
			out.Sources[i] = orig
			continue
		}
		wrap := path.Join("_bundle", pkg, "_w_"+strings.ReplaceAll(src, "/", "_"))
		out.Sources[i] = wrap
		files = append(files, BundleFile{Path: wrap, Content: wrapperSource(src, defines)})
	}
	var names []string
	for d := range dirs {
		names = append(names, d)
	}
	sort.Strings(names)
	var cflags []string
	for _, d := range names {
		cflags = append(cflags, "-I$(srcdir)/Modules/"+d)
	}
	out.CFlags = append(cflags, keep...)
	return out, files, nil
}

func initRenameMacro(m config.PyModule) string {
	builtin := BuiltinName(m.Name)
	leaf := m.Name
	if i := strings.LastIndex(m.Name, "."); i >= 0 {
		leaf = m.Name[i+1:]
	}
	if m.Init != "" {
		leaf = m.Init
	}
	from, to := "PyInit_"+leaf, "PyInit_"+builtin
	if from == to {
		return ""
	}
	return from + " " + to
}

func cutDashD(f string) (name, val string, ok bool) {
	rest, ok := strings.CutPrefix(f, "-D")
	if !ok || rest == "" {
		return "", "", false
	}
	name, val, _ = strings.Cut(rest, "=")
	return name, val, true
}

func wrapperSource(include string, defines []string) []byte {
	var b strings.Builder
	b.WriteString("/* generated: makesetup cannot express -Dname=value */\n")
	for _, d := range defines {
		b.WriteString("#define ")
		b.WriteString(d)
		b.WriteString("\n")
	}
	fmt.Fprintf(&b, "#include %q\n", include)
	return []byte(b.String())
}

// A dotted module is registered under its flattened builtin name; see
// BuiltinName.
func moduleLine(m config.PyModule) (string, error) {
	name := BuiltinName(m.Name)
	if !cIdent.MatchString(name) {
		return "", fmt.Errorf("gen: module %q has no valid builtin name", m.Name)
	}
	if len(m.Sources) == 0 {
		return "", fmt.Errorf("gen: module %q has no sources", m.Name)
	}
	parts := append([]string{name}, m.Sources...)
	parts = append(parts, m.CFlags...)
	parts = append(parts, m.Libs...)
	for _, p := range parts {
		if strings.ContainsAny(p, " \t\n=") {
			return "", fmt.Errorf("gen: module %q: makesetup cannot express the argument %q", m.Name, p)
		}
	}
	return strings.Join(parts, " "), nil
}

func parseSetupAsset(src []byte) ([]byte, map[string][]byte, error) {
	known := map[string]bool{"core": true, "full": true, "test": true}
	sections := map[string][]byte{}

	preamble := &bytes.Buffer{}
	bufs := map[string]*bytes.Buffer{}
	cur := preamble
	for _, line := range strings.SplitAfter(string(src), "\n") {
		rest, isMarker := strings.CutPrefix(line, sectionMarker)
		if !isMarker {
			cur.WriteString(line)
			continue
		}
		name := strings.TrimSpace(rest)
		if !known[name] {
			return nil, nil, fmt.Errorf("gen: Setup asset names unknown section %q", name)
		}
		if _, dup := bufs[name]; dup {
			return nil, nil, fmt.Errorf("gen: Setup asset repeats section %q", name)
		}
		cur = &bytes.Buffer{}
		bufs[name] = cur
	}
	for n, buf := range bufs {
		sections[n] = buf.Bytes()
	}
	return preamble.Bytes(), sections, nil
}
